        var query = hasQuery ? writtenQuery
            : metric ? javaTrim(catalogueIdentity(type, metric, component.match)) : null;
        var writtenUnit = json.unit === undefined || json.unit === null ? null : String(jsonText(json.unit));
        var unit = (writtenUnit === null || javaTrim(writtenUnit) === '') && metric ? (metric.unit || '')
            : writtenUnit === null ? '' : javaTrim(writtenUnit);
