        if (!band || kpi.reducer.kind === 'slope') return;       // Reducer.Kind.canBeNegative
        if (band.op !== 'lt' && band.op !== 'lte') return;
        var negativeOnly = band.op === 'lt' ? band.value <= 0 : band.value < 0;
